    {
        public void Execute(ExecutionResult result)
        {
            foreach (var c in Object.FindObjectsByType<Collider>(FindObjectsSortMode.None))
                if (c.GetInstanceID() == 945330 || c.GetInstanceID() == 962910)
                {
                    string path = c.name;
                    var t = c.transform.parent;
                    while (t)
                    {
                        path = t.name + "/" + path;
                        t = t.parent;
                    }

